//! Generating a starter `.bumper.toml` configuration file.
use std::{
    fs,
    io::{ErrorKind, Write},
    path::Path,
};

use anyhow::{Context, Result, bail};
use semver::Version;

use crate::{
    cargo::PACKAGE_VERSION_KEY,
    config::{BUMPER_CONFIG_FILE, VersioningType},
    version::YearMonth,
};

/// Starting point for the configuration generated by [`create`].
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Start {
    /// Version written as `current_version`.
    pub current_version: Version,
    /// Dotted key of the version in `Cargo.toml`, used for the generated `key` rule.
    pub key: &'static str,
}

impl Start {
    /// Return the starting point used when `Cargo.toml` declares no version.
    ///
    /// The version is `0.1.0` for SemVer, or `<year>.<month>.0` from `today` for CalVer, and the
    /// rule targets `package.version`.
    pub fn default_for(versioning_type: VersioningType, today: YearMonth) -> Self {
        let current_version = match versioning_type {
            VersioningType::Semver => Version::new(0, 1, 0),
            VersioningType::Calver => Version::new(today.year, today.month, 0),
        };

        Self {
            current_version,
            key: PACKAGE_VERSION_KEY,
        }
    }
}

/// Render the starter configuration used by [`create`].
///
/// `current_version` is taken from `start`, and the template includes a single rule that bumps
/// `start.key` in `./Cargo.toml`.
fn render(versioning_type: VersioningType, start: &Start) -> String {
    let current_version = &start.current_version;
    let key = start.key;

    let versioning_type = match versioning_type {
        VersioningType::Semver => "semver",
        VersioningType::Calver => "calver",
    };

    format!(
        r#"[tool.bumper]
current_version = "{current_version}"
versioning_type = "{versioning_type}"

[[tool.bumper.files]]
file = "./Cargo.toml"
key = "{key}"
"#
    )
}

/// Write a starter `.bumper.toml` into `root`.
///
/// The configuration starts from `start`. An existing configuration file is only replaced when
/// `ignore_existing` is set; otherwise an existing file is never clobbered.
///
/// # Errors
///
/// Returns an error if the configuration file already exists (and `ignore_existing` is not set), or
/// if it cannot be written.
pub fn create(
    root: &Path,
    versioning_type: VersioningType,
    start: &Start,
    ignore_existing: bool,
) -> Result<()> {
    let cfg_file = root.join(BUMPER_CONFIG_FILE);
    let contents = render(versioning_type, start);

    if ignore_existing {
        fs::write(&cfg_file, contents).with_context(|| {
            format!(
                "Could not write configuration file '{}'",
                cfg_file.display()
            )
        })?;
        return Ok(());
    }

    let mut file = match fs::OpenOptions::new()
        .write(true)
        .create_new(true)
        .open(&cfg_file)
    {
        Ok(file) => file,
        Err(e) if e.kind() == ErrorKind::AlreadyExists => {
            bail!("Configuration file already exists: '{BUMPER_CONFIG_FILE}'")
        }
        Err(e) => {
            return Err(e).with_context(|| {
                format!(
                    "Could not write configuration file '{}'",
                    cfg_file.display()
                )
            });
        }
    };

    file.write_all(contents.as_bytes()).with_context(|| {
        format!(
            "Could not write configuration file '{}'",
            cfg_file.display()
        )
    })?;
    Ok(())
}

